const studentClashes = `-- name: StudentClashes :many
SELECT a.lesson_id, a.student_id, s.name AS student_name, b.lesson_id AS other_lesson_id,
       lower(b.time_range)::timestamptz AS other_starts_at,
       upper(b.time_range)::timestamptz AS other_ends_at
FROM lesson_participants a
JOIN lesson_participants b
  ON b.student_id = a.student_id AND b.lesson_id <> a.lesson_id
 AND b.active AND b.time_range && a.time_range
JOIN students s ON s.workspace_id = a.workspace_id AND s.id = a.student_id
WHERE a.workspace_id = $1 AND a.lesson_id = ANY($2::uuid[]) AND a.active
ORDER BY a.lesson_id, other_starts_at, b.lesson_id
`

type StudentClashesParams struct {
	WorkspaceID uuid.UUID
	LessonIds   []uuid.UUID
}

type StudentClashesRow struct {
	LessonID      uuid.UUID
	StudentID     uuid.UUID
	StudentName   string
	OtherLessonID uuid.UUID
	OtherStartsAt time.Time
	OtherEndsAt   time.Time
}

// The same for students booked into two lessons at once.
func (q *Queries) StudentClashes(ctx context.Context, arg StudentClashesParams) ([]StudentClashesRow, error) {
	rows, err := q.db.Query(ctx, studentClashes, arg.WorkspaceID, arg.LessonIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StudentClashesRow
	for rows.Next() {
		var i StudentClashesRow
		if err := rows.Scan(
			&i.LessonID,
			&i.StudentID,
			&i.StudentName,
			&i.OtherLessonID,
			&i.OtherStartsAt,
			&i.OtherEndsAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const tutorClashes = `-- name: TutorClashes :many
SELECT a.lesson_id, a.membership_id, b.lesson_id AS other_lesson_id,
       lower(b.time_range)::timestamptz AS other_starts_at,
       upper(b.time_range)::timestamptz AS other_ends_at
FROM lesson_tutors a
JOIN lesson_tutors b
  ON b.membership_id = a.membership_id AND b.lesson_id <> a.lesson_id
 AND b.active AND b.time_range && a.time_range
WHERE a.workspace_id = $1 AND a.lesson_id = ANY($2::uuid[]) AND a.active
ORDER BY a.lesson_id, other_starts_at, b.lesson_id
`

type TutorClashesParams struct {
	WorkspaceID uuid.UUID
	LessonIds   []uuid.UUID
}

type TutorClashesRow struct {
	LessonID      uuid.UUID
	MembershipID  uuid.UUID
	OtherLessonID uuid.UUID
	OtherStartsAt time.Time
	OtherEndsAt   time.Time
}

// For each given lesson, other active lessons overlapping it for the same
// tutor. Ranges are half-open: back-to-back lessons do not clash.
func (q *Queries) TutorClashes(ctx context.Context, arg TutorClashesParams) ([]TutorClashesRow, error) {
	rows, err := q.db.Query(ctx, tutorClashes, arg.WorkspaceID, arg.LessonIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TutorClashesRow
	for rows.Next() {
		var i TutorClashesRow
		if err := rows.Scan(
			&i.LessonID,
			&i.MembershipID,
			&i.OtherLessonID,
			&i.OtherStartsAt,
			&i.OtherEndsAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

